import math
import numpy as np
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

n = 3
k_values = [1, 2, 3, 4, 5, 6]
x_values = {}

for k in k_values:
    numbers = list(range(k, k + n))
    x = list_lcm(numbers)
    x_values[k] = x
    print(f"x_{k} = lcm({k}, {k+1}, {k+2}) = {x}")

# Check the relationship between consecutive terms
print("\nChecking consecutive terms:")
for k in range(1, len(k_values)):
    print(f"x_{k+1} > x_{k} ? {x_values[k+1] > x_values[k]}")
